// src/components/Home.tsx
import React, { useMemo, useState, useEffect } from "react";
import "../styles/Home.css";
import BatterTable from "./BatterTable";
import useFetchBatters from "../hooks/useFetchBatters";
import Spinner from "./Spinner";
import Button from "./Button";
import { signOut } from "firebase/auth";
import { auth } from "../firebase";
import { useAuth } from "../context/AuthContext";
import Searchbar from "./Searchbar";

// 1) Define the minimal Batter shape
interface Batter {
  batter_name: string;
  // add any other fields you expect here:
  // team: string;
  // hits: number;
  // etc.
}

function Home() {
  const [clearData, setClearData] = useState(false);
  const [getTomorrow, setGetTomorrow] = useState(false);
  const [isTomorrowData, setIsTomorrowData] = useState(false);

  // 2) Tell the hook that T = Batter
  const { data, error, isLoading, refetch, cancel } = useFetchBatters<Batter>({
    enabled: false,
  });

  const [abortController, setAbortController] = useState<AbortController | null>(null);
  const [timer, setTimer] = useState(0);
  const [intervalId, setIntervalId] = useState<NodeJS.Timeout | null>(null);
  const [showTimer, setShowTimer] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const { currentUser } = useAuth();

  // … your existing handlers (handleRefresh, handleCancel, etc.) …

  // Now TS knows that data is Batter[], so `b.batter_name` is valid
  const filteredData = useMemo(() => {
    return data.filter((b) =>
      b.batter_name.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [data, searchQuery]);

  // … the rest of your render …
  return (
    <div className="App">
      {/* … */}
      <Searchbar handleSearch={setSearchQuery} />
      <div className="Leaderboard-table">
        {isLoading ? <Spinner /> : <BatterTable data={filteredData} />}
      </div>
      {error && <p style={{ color: "red" }}>{error}</p>}
    </div>
  );
}

export default Home;
